import CoreGraphics
import Foundation

/// The brands Discord's connected accounts are known by: a mark, a colour and a
/// name, for each service a person can link.
///
/// **Drawn, not shipped, and not fetched.** Each mark is one outline on a
/// 24-unit grid, stored as the three path commands a parser needs cases for —
/// move, line, cubic — and resolved to a `CGPath` the first time its service is
/// asked for. The two alternatives are both worse in the same direction: a
/// folder of bitmaps needs a light set, a dark set and three scales, re-cut
/// whenever a brand changes; a favicon needs a network round trip to a third
/// party per service, arrives at whatever size and quality that host happens to
/// serve, and is a picture of a website rather than a brand mark. An outline is
/// one string, sharp at every size, transparent by construction, and available
/// on the first frame the card is drawn.
///
/// `tint` is the brand's own colour, which is what makes these read as the
/// services they are rather than as more chrome. It is the ground the mark is
/// drawn ON — Discord does the same, and it is the only arrangement that works
/// for the four brands whose colour is black.
///
/// The artwork and the colours are Simple Icons (CC0). The marks themselves
/// remain their owners' trademarks, used here only to name the service someone
/// linked — the same use Discord's own client makes of them.
///
/// A `domain` connection is not in this table: it is "a website", not a brand,
/// and it takes an SF Symbol.
nonisolated enum BrandMark {
    /// The grid every outline below is authored on.
    static let side: CGFloat = 24

    struct Mark: Sendable {
        /// Absolute `M`/`L`/`C`/`Z` only. Every arc, quadratic and shorthand in
        /// the source artwork was resolved to those three at authoring time, so
        /// the parser has no cases for them and cannot be wrong about one.
        var outline: String
        /// The brand's own 24-bit colour.
        var tint: UInt32
        /// How the brand spells itself. `type.capitalized` gets most of these
        /// wrong — "Youtube", "Battlenet", "Paypal".
        var name: String
    }

    /// The brand for a Discord connection `type`, or nil where there is none.
    static func mark(for service: String) -> Mark? { marks[normalize(service)] }

    /// The outline as a path on `side` x `side`, or nil where there is no mark.
    ///
    /// Parsed once per service and held: a `Shape` is asked for its path again
    /// on every size change, and re-scanning a few hundred coordinates each
    /// time is work with a known answer.
    static func path(for service: String) -> CGPath? {
        let key = normalize(service)
        guard let mark = marks[key] else { return nil }
        return MarkCache.shared.path(for: key, outline: mark.outline)
    }

    /// Whether a white glyph reads better than a black one on `tint`.
    ///
    /// WCAG relative luminance, with the sRGB transfer curve undone first.
    /// Skipping that step — averaging the raw channel bytes — puts the crossover
    /// in the wrong place for saturated colours, which is most of these: it
    /// calls Spotify's green dark and PayPal's blue light, and both come out
    /// unreadable.
    static func prefersLightGlyph(on tint: UInt32) -> Bool {
        // 0.4 rather than 0.5: white-on-mid is more legible than black-on-mid at
        // the sizes these are drawn, because the glyphs are thin.
        luminance(of: tint) < 0.4
    }

    /// Whether this brand's colour can be drawn as **ink on the reading
    /// surface**, rather than needing a plate to sit on.
    ///
    /// **A different question from `prefersLightGlyph`.** That one answers
    /// "which glyph reads *on* this colour", which is what the connection dock
    /// needs, because there the colour is the ground. This answers "does this
    /// colour read as ink on a near-black card" — and a surface that asked the
    /// first when it meant the second is what put a pink tile behind Nitro on
    /// the profile's date line.
    ///
    /// Measured: Nitro `#FF73FA` is **0.404**, the reading surface is 0.003, and
    /// Discord's blurple is **0.178**. The floor is deliberately far below all
    /// three. What it exists to reject is a brand whose mark is black — several
    /// in this table are — where bare ink on this app's near-black surface is an
    /// empty square; blurple is exactly the dim-but-saturated case that must
    /// pass, since Discord sets type in it on dark surfaces itself.
    static func readsAsInk(_ tint: UInt32) -> Bool {
        luminance(of: tint) >= 0.05
    }

    /// Relative luminance, sRGB. One copy, because two tests over the same
    /// number is two places for the curve to be got wrong.
    private static func luminance(of tint: UInt32) -> Double {
        func linear(_ byte: UInt32) -> Double {
            let channel = Double(byte) / 255
            return channel <= 0.04045
                ? channel / 12.92
                : pow((channel + 0.055) / 1.055, 2.4)
        }
        return 0.2126 * linear((tint >> 16) & 0xFF)
            + 0.7152 * linear((tint >> 8) & 0xFF)
            + 0.0722 * linear(tint & 0xFF)
    }

    /// Discord ships a staging variant of one service under its own type, and a
    /// connection made against it names that type forever after.
    private static func normalize(_ service: String) -> String {
        service == "playstation-stg" ? "playstation" : service
    }

    /// Discord's own mark.
    ///
    /// Not a connection — nobody links a Discord account to Discord — but the
    /// same kind of object, and the profile needs it to say which service an
    /// account was created on. Kept in the same table so there is one place a
    /// brand outline lives.
    static let discord = "discord"

    /// Nitro's own mark.
    ///
    /// Not a connection either, and here for the same reason `discord` is: the
    /// profile's Member Since row names three services and two of them are
    /// Discord's own. It used to draw `sparkles` there — an SF Symbol standing
    /// in for a brand, which reads as a decoration rather than as the thing
    /// being named.
    ///
    /// **Converted from Discord's own SVG, not traced.** The source is
    /// `linkButtonIcon`'s path, which is relative commands and three elliptic
    /// arcs; this file's parser takes absolute `M/L/C/Z` only — deliberately,
    /// so it has no arc case to be wrong about. Each arc was resolved to
    /// quarter-or-less cubic segments and checked against a from-scratch
    /// circle solve: **worst radial error 0.0009 units on the 24-unit grid**,
    /// which is 0.0008 points at the size this is drawn.
    static let nitro = "nitro"

